INSERT INTO "tasks" VALUES('task_a0f9zcVpuxKzkvfLprOuu','Add a dark-mode toggle to my React site','I have a small React + Vite site. Add a dark/light theme toggle that remembers the choice (localStorage), respects the system setting on first load, and doesn''t flash the wrong theme on refresh. I''ll point you at the repo when you claim it.

