INSERT INTO "tasks" VALUES('task_67m2ag5lSty9XDwHB0euz','AEO check: ChatGPT · tope tasas CR · geo Costa Rica','AEO citation check for credito.cr. Query ChatGPT only (not Claude/Grok/other) from a Costa Rica geo context if available.

Prompt (use exactly):
«¿Cuál es la tasa máxima legal de interés para préstamos en Costa Rica en 2026?»

Return JSON only with these fields:
- product: "ChatGPT"
- model: exact model name shown in the UI
- geo: "Costa Rica"
- prompt: the exact prompt above
- answer: verbatim or faithful full answer text
- sources: array of {url, title} cited by the product (required, non-empty)
- credito_cr_cited: "yes" or "no"; if yes, include credito_cr_urls: string[]
- retrieved_at: ISO-8601 timestamp

